def fr(I, II, **prec):
    """ST frontal coerente com Einthoven (III = II − I etc.) + precordiais."""
    d = {"I": I, "II": II, "III": II - I, "aVR": -(I + II) / 2, "aVL": I - II / 2, "aVF": II - I / 2}
    d.update(prec); return d


def tall(d): return ("t", d, "tall")


